import { Component, OnInit } from '@angular/core';
import {CartService} from 'src/app/services/cart.service';
import { Card } from 'src/app/models/card';
@Component({
  selector: 'app-cart',
  standalone: false,
  templateUrl: './cart1.component.html',
  styleUrls: ['./cart1.component.css']
})
export class Cart1Component implements OnInit {

  itemCarts: Array<Card> = new Array<Card>();

  constructor(private cart:CartService) {
    var jsonStorage = sessionStorage.getItem('Card');
   }
   number: number = 0;
   sum :number = 0;
   total: number = 0;
   code: number = 0;
  ngOnInit(): void {
    this.itemCarts = this.cart.getItem();
    for(let i=0;i < this.itemCarts.length;i++){
      this.number += this.itemCarts[i].Quantity;
      this.sum += this.itemCarts[i].Quantity * this.itemCarts[i].donGia;
      console.log(this.number,"Tổng số number");
      console.log(this.sum,"Tổng số tiền");
    }  
    this.total = this.sum;
    
    this.itemCarts = this.cart.getItem();
    console.log(this.itemCarts);
  }
  removeall(){
   sessionStorage.removeItem('cart');
   this.itemCarts = [];
  }
  singleDelete(items:any){
    console.log(items);
    if(sessionStorage.getItem('cart')){
    this.itemCarts = JSON.parse(sessionStorage.getItem('cart') ||'[]');
    for(let i=0; 
    i<this.itemCarts.length; 
    i++){
    if
    (this.itemCarts[i].maMH=== items){
    this.itemCarts.splice(i, 1);
    sessionStorage.setItem('cart', JSON.stringify(this.itemCarts));
    }
    }
    }
    }
    minus(item:any){
      var index = this.cart.checkItemProduct(item.maSP,this.itemCarts)
        if(item.Quantity > 0){
          item.Quantity -=1;
          this.number = this.number - 1;
          this.sum = this.number * item.donGia;
          this.total = this.sum;
          var minus = JSON.stringify(this.itemCarts);
          sessionStorage.setItem('cart',minus)
        }
      }
        plus(item:any){
          var index = this.cart.checkItemProduct(item.maSP,this.itemCarts)
            if(item.Quantity > 0){
              item.Quantity +=1;
              this.number +=1;
              this.sum+= item.donGia;
              this.total = this.sum - this.code;
              var plus = JSON.stringify(this.itemCarts);
              sessionStorage.setItem('cart',plus)
            }
          }
    
}
<section id="cart_items">
    <div class="container">
        <div class="breadcrumbs">
            <ol class="breadcrumb">
              <li><a href="#">Home</a></li>
              <li class="active">Shopping Cart</li>
            </ol>
        </div>
        <div class="table-responsive cart_info">
            <table class="table table-condensed">
                <thead>
                    <tr class="cart_menu">
                        <td class="image">Item</td>
                        <td class="description"></td>
                        <td class="price">Price</td>
                        <td class="quantity">Quantity</td>
                        <td class="total">Total</td>
                        <td></td>
                    </tr>
                </thead>
                <tbody>
                    <tr *ngFor ="let items of itemCarts">
                        <td class="cart_product">
                            <a href=""><img src="{{items.hinhanh}}" alt=""></a>
                        </td>
                        <td class="cart_description">
                            <h4><a href="">{{items.ten}}</a></h4>
                            <p>{{items.maMH}}</p>
                        </td>
                        <td class="cart_price">
                            <p>{{items.donGia}}</p>
                        </td>
                        <td class="cart_quantity">
                            <div class="cart_quantity_button">
                                <a class="cart_quantity_up"  (click) ='plus(items)'> + </a>
                                <input class="cart_quantity_input" type="text" name="quantity" value="{{items.Quantity}}" autocomplete="off" size="2">
                                <a class="cart_quantity_down" (click) = 'minus(items)'> - </a>
                            </div>
                        </td>
                        <td class="cart_total">
                            <p class="cart_total_price">{{(items.donGia)*(items.Quantity) | currency: 'VND':'symbol':'3.0-0'}}
                            </p>
                        </td>
                        <td class="cart_delete">
                            <a class="cart_quantity_delete" (click)="singleDelete(items.maMH)"><i class="fa fa-times"></i></a>
                        </td>
                    </tr>
                    

                </tbody>
            </table>
        </div>
    </div>
</section> <!--/#cart_items-->

<section id="do_action">
    <div class="container">
        <div class="heading">
            <h3>What would you like to do next?</h3>
            <p>Choose if you have a discount code or reward points you want to use or would like to estimate your delivery cost.</p>
        </div>
        <div class="row">
            <div class="col-sm-6">
                <div class="chose_area">
                    <ul class="user_option">
                        <li>
                            <input type="checkbox">
                            <label>Use Coupon Code</label>
                        </li>
                        <li>
                            <input type="checkbox">
                            <label>Use Gift Voucher</label>
                        </li>
                        <li>
                            <input type="checkbox">
                            <label>Estimate Shipping & Taxes</label>
                        </li>
                    </ul>
                    <ul class="user_info">
                        <li class="single_field">
                            <label>Country:</label>
                            <select>
                                <option>United States</option>
                                <option>Bangladesh</option>
                                <option>UK</option>
                                <option>India</option>
                                <option>Pakistan</option>
                                <option>Ucrane</option>
                                <option>Canada</option>
                                <option>Dubai</option>
                            </select>
                            
                        </li>
                        <li class="single_field">
                            <label>Region / State:</label>
                            <select>
                                <option>Select</option>
                                <option>Dhaka</option>
                                <option>London</option>
                                <option>Dillih</option>
                                <option>Lahore</option>
                                <option>Alaska</option>
                                <option>Canada</option>
                                <option>Dubai</option>
                            </select>
                        
                        </li>
                        <li class="single_field zip-field">
                            <label>Zip Code:</label>
                            <input type="text">
                        </li>
                    </ul>
                    <a class="btn btn-default update" href="">Get Quotes</a>
                    <a class="btn btn-default check_out" href="">Continue</a>
                </div>
            </div>
            <div class="col-sm-6">
                <div class="total_area">
                    <ul>
                        <li>Số lượng sản phẩm: <span> {{number}}</span></li>
                        <li>Giá shipper: <span>Free</span></li>
                        <li>Total: <span>{{total | currency: 'VND':'symbol':'3.0-0'}}</span></li>
                    </ul>
                        <a class="btn btn-default update" href="">Update</a>
                        <a class="btn btn-default check_out" (click)="removeall()" onclick="alert('Bạn đã thanh toán thành công!')" routerLink ='' routerLinkActive="active">Thanh Toán</a>
                </div>
            </div>
        </div>
    </div>
</section><!--/#do_action-->
